sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var beds = [];

    var gr = new GlideRecordSecure('x_2130921_caresy_0_bed');
    gr.orderBy('number');
    gr.query();

    while (gr.next()) {

        beds.push({
            sys_id: gr.getUniqueValue(),

            bed_number: gr.getValue('number'),
            bed_name: gr.getValue('bed_name'),

            ward_sys_id: gr.getValue('ward'),
            ward: gr.getDisplayValue('ward'),

            department_sys_id: gr.getValue('department'),
            department: gr.getDisplayValue('department'),

            location_sys_id: gr.getValue('location'),
            location: gr.getDisplayValue('location'),

            bed_status: gr.getDisplayValue('bed_status'),
            bed_type: gr.getDisplayValue('bed_type'),

            floor: gr.getValue('floor'),

            active: gr.getValue('active') == '1'
        });
    }

    response.setStatus(200);

    response.setBody({
        success: true,
        count: beds.length,
        beds: beds
    });

})(request, response);
